from fractions import Fraction as F
from math import factorial
def bn(n,k):
 r=F(1)
 for i in range(k):r*=F(n-i,i+1)
 return r
def c(g,q,a,b):
 h={-a-g+j:F(factorial(g))*bn(-a,g-j)*bn(a-4,j)*(-1)**j for j in range(g+1)};Q=q+2;s=-1 if b=='-' else 1;o={}
 for e,x in h.items():
  v=e+1+s*Q;o[e]=o.get(e,F())+x*v;o[e+1]=o.get(e+1,F())+x*(v-g)
 o={e:x for e,x in o.items() if x};return o if b=='-' else {e+Q:-x for e,x in o.items()}
def sub(v,w,z):
 for e,x in w.items():
  v[e]=v.get(e,F())-z*x
  if not v[e]:del v[e]
def build(g,q,N):
 E=[];R=[];P=[];B=[];D={}
 for a in range(N+1):
  for b in '-+':
   v=c(g,q,a,b);r={}
   for i,p in enumerate(P):
    z=v.get(p,F())
    if z:
     sub(v,E[i],z)
     for j,x in R[i].items():r[j]=r.get(j,F())-z*x
   if v:
    p=min(v);z=v[p];E.append({e:x/z for e,x in v.items()});r={j:x/z for j,x in r.items()};r[len(P)]=F(1,z);R.append(r);P.append(p);B.append((a,b))
   else:D[(a,b)]={j:-x for j,x in r.items()}
 return B,D
for g,q in [(6,3),(6,8),(6,13)]:
 B,D=build(g,q,80);print('case',g,q)
 for N in [20,40,60,80]:
  for rho in [1.25,1.5,2.0]:
   rows=[0.0]*len(B);cols=[]
   for (a,b),r in D.items():
    if b!='+' or a>N:continue
    z=0.
    for j,x in r.items():
     y=float(abs(x))*rho**(B[j][0]-a);z+=y;rows[j]+=y
    cols.append(z)
   print(N,rho,f'C={max(cols):.3g}',f'R={max(rows):.3g}')
